from 写入第二遍 import add
add('10_004',2.5,'16:9，越青背肩的双层中景，青耳尖与长发占画面左侧近层，董白在右后完整站姿；相机随青向前短移，董白在后层逐渐缩小。','青迈步从董白前方走过，肩头与耳尖掠过镜头左侧，长发延后横扫两人之间；她步子稳定地接成两下。董白原本抬高的下巴顿住，圆眼追着青，嘴松开吐出短问，身体留在原地，双马尾在背后垂着。','两人间的窄隙露蓝灰天空与分层浅灰云，下缘一小块灰绿石铺地面随跟移显出。','正上方冷白漫射保持，银发亮面在近处扫过，董白脸部保持中性柔补光。','两下鞋底落石声，长发扫过衣背，董白鞋底一声很轻的重心擦响。',ja=['は？'],tone='董白预期中的争执落空，反问短而困惑。',kind='mixed',phase='process',node={'青.位置':'走过董白，沿平台朝武士前行','董白.位置':'留在青身后'},meaning='青背肩与横扫长发在近处，董白后方惊讶全身；真实步行越过，保持原格前后关系。',characters=['青','董白'],card={'opening':'青的平静承认打断了董白训人的节奏。','beats':['青从她面前走过，长发晚一拍扫开','董白追视，抬下巴停住，短问'],'coupling':'脚步持续，反问落在青已经向前的背影上。','landing':'青在前、董白在后，行动权转回青。'})
add('11_001',5,'16:9，青正面头肩近景，脸居画面中央，抬起的手从画面左侧进入，手指横向靠近嘴角；机位在前方缓退，与她最后半步同步停稳。','青向武士的方向再走半步便站稳，眉毛压低，半垂双眼直视前方；她把手抬到嘴边，一根手指停在唇边。第一句说得平静，第二句她微微抬起下巴，嘴角不再迟疑，手腕继续送近，话尾收净时指尖刚触到齿间入口。','头肩两侧留蓝灰云天，低处米灰烟尘缓慢向平台外流，身后灰绿石铺地面只露极窄一线。','云天冷白柔光在脸与手背铺开，压低眉毛投出浅灰细影。','最后半步鞋声落定，护腕布料轻响，呼吸收束成短吐气。',ja=['勝てばいい。','いつまでも怖じ気づいて、どうするの。'],tone='第一句稳而直接，第二句像对自己下令，末尾落定决心。',kind='mixed',phase='anticipation',node={'青.位置':'董白前方，面向武士站稳','青.手指':'已抬到唇边，准备咬住'},meaning='青正面半垂眼、压眉与抬手指到嘴边保留，两句说完才进入咬合。',characters=['青'],card={'opening':'青从对自己后果的顾虑转为先赢下眼前一战。','beats':['站稳抬手，第一句平静落下','微抬下巴对自己下令，手指抵近嘴角'],'coupling':'话先说完整，咬合动作在尾句之后到达。','landing':'目光已定，手指抵口，下一镜完成接触。'})
add('11_002',1.5,'16:9，嘴与手指的极特写，齿间接触点居画面中央偏左，下巴位于右下，眼睛始终在画外；固定机位。','青把自己的手指送进齿间，牙齿合紧，唇角向两侧拉开一小截；手腕稳住，指节在咬合瞬间短短绷起，最后停在齿与手指牢牢接触的位置，银白发丝在下颌旁落定。','脸与发丝之外只留两块浅蓝灰天空，其余背景完全被主体遮住。','上方冷白柔光保持，嘴角与手指下侧压出浅冷灰，接触点清楚。','一声短脆的咬合拟音，护腕轻绷后静下，风声压低。',kind='action',phase='contact',node={'青.手指':'齿间咬住，接触稳定；本批在此结束'},meaning='用户确认的咬自己手指；只落实齿与手指接触，不补出血或招式效果。',characters=['青'])
